function get_current_page() {
    $script = basename($_SERVER['PHP_SELF'], '.php');
    return $script;
}

function active_class($page, $current) {
    return ($page === $current) ? ' active' : '';
}

function h($str) {
    return htmlspecialchars($str, ENT_QUOTES | ENT_HTML5, 'UTF-8');
}

